CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'EDITOR',"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastLoginAt" TIMESTAMP(3),CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
