CREATE TABLE "Media" ("id" TEXT NOT NULL,"filename" TEXT NOT NULL,"originalFilename" TEXT NOT NULL,"storageProvider" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"publicUrl" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"mediaType" "MediaType" NOT NULL,"width" INTEGER,"height" INTEGER,"duration" DOUBLE PRECISION,"fileSize" INTEGER,"alt" TEXT,"caption" TEXT,"focalX" INTEGER DEFAULT 50,"focalY" INTEGER DEFAULT 50,"posterMediaId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Media_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"category" TEXT NOT NULL,"summary" TEXT NOT NULL,"description" TEXT,"status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT',"featured" BOOLEAN NOT NULL DEFAULT false,"featuredOrder" INTEGER,"year" INTEGER,"clientName" TEXT,"services" TEXT[],"heroMediaId" TEXT,"thumbnailMediaId" TEXT,"beforeMediaId" TEXT,"afterMediaId" TEXT,"videoMediaId" TEXT,"videoPosterMediaId" TEXT,"ogImageId" TEXT,"seoTitle" TEXT,"seoDescription" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"publishedAt" TIMESTAMP(3),CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
